import boto3

def archive_image_assets(bucket_name, object_key, file_path):
    s3_client = boto3.client('s3')
    try:
        s3_client.upload_file(file_path, bucket_name, object_key)
        print(f'File {file_path} uploaded to {bucket_name}/{object_key}')
    except Exception as e:
        print(f'Error uploading file: {e}')

# Example usage:
# archive_image_assets('my-image-assets-bucket', 'image-analysis/artifacts/description.txt', 'path/to/local/description.txt')

import boto3

def check_unsafe_text(text):
    comprehend = boto3.client('comprehend')
    response = comprehend.detect_sentiment(
        Text=text,
        LanguageCode='en'
    )
    sentiment = response['Sentiment']
    if sentiment == 'NEGATIVE':
        return True
    else:
        return False

import boto3

def summarize_image(image_bytes):
    client = boto3.client('rekognition')
    response = client.detect_labels(
        Image={'Bytes': image_bytes},
        MaxLabels=10
    )
    labels = [label['Name'] for label in response['Labels']]
    return ' '.join(labels)

